"""Audit the atomic-ledger follow-up, retaining the rejected locked-cache report."""
import json,statistics as st
import upload_cache_report as previous
from protocol import sha
R=previous.R
load=lambda name:json.loads((R/f'gpu-upload-cache-atomic-{name}-2026-10-29.json').read_text())
med=st.median
q=load('qualification');previous.identity(q)
assert len(q['checks'])==108 and sum(r['comparisons'] for r in q['checks'])==432 and all(r['passed'] for r in q['checks'])
assert len(q['oracles'])==8 and all(r['metrics']['max_error_bound_ratio']<=1 for r in q['oracles'])
tests=load('tests');previous.identity(tests);assert tests['runtime_tests']==200
studies={k:load(k) for k in ('aa','repeat')}
for data in studies.values():
 previous.audit(data)
 assert data['protocol']['blocks']==3 and data['protocol']['target_ms']==1000 and data['protocol']['max_iterations']==8192

def rows(data,g):return [r for r in data['pairs'] if tuple(r['group'])==g]
def values(data,g):return [r['time_reduction']*100 for r in rows(data,g)]
groups=sorted({tuple(r['group']) for r in studies['repeat']['pairs']})
lines=['# Atomic budget accounting and bounded upload reuse — 29 October 2026','','The [first cache candidate](gpu-upload-cache-2026-10-29.md) passed correctness but was not promoted: longer batches found a 7.92% resident 64×256 regression. It locked every payload reservation and release. This revision uses an atomic live-plus-idle reservation ledger; only cache mutation and eviction take the mutex. The original results, including the initial 45.63% input regression that did not reproduce in longer batches, remain retained.','','## Contract and correctness','','The cache still retains at most 16 MiB and 64 exact-size/device shared-upload buffers inside the existing 64 MiB default payload budget. Every logical byte and padding is overwritten before publication. Last-owner retirement requires no admitted work; pending/concurrent resources are discarded. Private outputs, scratch, staging and parameter arenas remain excluded. Runtime destruction closes/trims the cache, and zero capacity disables it. Numerical operations, checkpoints, failure-injection order and cancellation/fault precedence are unchanged.','','The atomic ledger reserves total capacity before publishing live bytes, releases live ownership before total capacity, and leaves the total unchanged during live/idle transfers. Cache eviction releases actual backing before returning its reservation. Racing allocations cannot spend the same space. A new test makes eight callers compete for exactly two live allocations across 32 rounds, including eviction of an existing idle buffer. It passes in debug, optimized, ASan/UBSan and TSan builds.','','200 runtime/support CTests passed after this revision, including all four upload suites, concurrency/failure/budget checks, encoding overlap, and module/fixed-shape/forwarding fixtures. Six long source-compilation integration fixtures and the long numeric CLI suites were not rerun after this private accounting change; their earlier passing results are retained in the first report. This is not a full compiler-suite claim. Fresh numerical qualification passes 432 changing-input full-output comparisons across cache limits, upload modes, runner policies and four shapes, plus eight independent high-precision oracle checks. Metal/shader validation is enabled for correctness and disabled for timing.','','## Longer-batch production comparison','','Frozen pre-cache production (`c542d414`) versus the actual revised runtime, using unchanged generated shaders and original timed driver loop. Apple M2 Max/macOS 27. Three adjacent ABBA/BAAB blocks per case; two warm-up and three measured rounds; adaptive 1,000 ms target, maximum 8,192 calls. The identical-build control covers the five previously unstable cases. All setup is excluded, all per-call work and all samples are retained. Positive percentages mean lower elapsed time. Absolute medians and median paired ratios summarize different distributions: percentages are calculated within adjacent pairs before aggregation. These small block counts and a single machine limit precision and generalization.','','| Batch × width | Upload mode | Old → new µs | Paired reduction | Full block range | Identical-build control |','|---|---|---:|---:|---:|---:|']
for g in groups:
 r=rows(studies['repeat'],g);v=values(studies['repeat'],g);aa=values(studies['aa'],g);m,d,mode=g
 control=f'{med(aa):+.2f}%' if aa else 'not measured'
 lines.append(f'| {m} × {d} | {("resident","input","all weights")[mode]} | {med(x["baseline_ns"] for x in r)/1000:.1f} → {med(x["current_ns"] for x in r)/1000:.1f} | {med(v):+.2f}% | {min(v):+.2f}% … {max(v):+.2f}% | {control} |')
confirmation={}
for study in ('aa','repeat'):
 data=json.loads((R/f'gpu-upload-cache-resident-confirm-{study}-2026-10-29.json').read_text());previous.audit(data)
 assert data['protocol']['blocks']==7 and data['protocol']['target_ms']==1000
 confirmation[study]=data
lines+=['','## Focused resident confirmation','','Resident 16×512 was the only median slowdown larger than 5% in the twelve-case atomic run. It therefore received a separately declared seven-block identical-build control and seven-block production repeat, with the same one-second target and frozen binaries. The original -8.29% result above is retained.','','| Study | Baseline → current µs | Paired reduction | Full block range |','|---|---:|---:|---:|']
for study,data in confirmation.items():
 v=values(data,(16,512,0));r=data['pairs']
 lines.append(f'| {study} | {med(x["baseline_ns"] for x in r)/1000:.1f} → {med(x["current_ns"] for x in r)/1000:.1f} | {med(v):+.2f}% | {min(v):+.2f}% … {max(v):+.2f}% |')
lines+=['','The original -8.29% median slowdown does not reproduce in the focused repeat (-0.97%); the identical-build control is -0.81%. This supports accepting the bounded upload optimization, but does not prove a zero resident cost or attribute every earlier swing to the removed mutex. Individual blocks remain volatile and all are retained. The accepted benefit is the repeatable 52.52–63.12% reduction in width-512 all-weight-upload time, and 22.91% at width256. No resident speedup is claimed.','','Independent cohorts must not be subtracted as a causal estimate. Resident cases have no upload-cache hits. The earlier same-executable off/on study establishes the large width-512 upload-reuse benefit, while this follow-up measures the complete revised runtime against pre-cache production. It does not establish a new GPU arithmetic speedup or close the remaining resident-compute/vendor-library gap.','','## Memory and external load','']
cache=[s for d in studies.values() for obs in d['cache_observations'] for s in obs['samples']]
lines.append(f'Maximum observed idle cache: {max(s["cached_bytes"] for s in cache):,} bytes; retained payload: {max(s["peak_retained_bytes"] for s in cache):,} bytes. Every recorded sample respects the existing 67,108,864-byte budget and the 16 MiB cache limit. These are observed peaks for this workload set. Idle retention is an explicit tradeoff, visible in the new retained/cache statistics; live-owner counters keep their old meaning. `trimUploadCache()` releases idle storage.')
lines+=['','No local builds, tests or profiling overlap timing. External CPU sampling does not establish GPU idleness. 100% means one CPU core.','','| Study | External CPU median | Maximum |','|---|---:|---:|']
for study in ('atomic-aa','atomic-repeat','resident-confirm-aa','resident-confirm-repeat'):
 d=json.loads((R/f'gpu-upload-cache-{study}-2026-10-29-load.json').read_text());cpu=[s['external_cpu_percent'] for s in d['samples']]
 lines.append(f'| {study} | {med(cpu):.1f}% | {max(cpu):.1f}% |')
lines+=['','## Reproduction','','`upload_cache_study.py` prepares the frozen candidate and performs numerical qualification. `upload_cache_atomic.py --phase measure --study aa|repeat --build DIR --output NEW.json` applies the declared longer-batch protocol without changing the executables or hot loop. `upload_cache_resident_confirm.py --phase measure --study aa|repeat --build DIR --output NEW.json` applies the focused seven-block resident protocol. `fair/upload_cache_atomic_report.py` audits source/artifact identities, both numerical qualifications, resource caps, retained test logs and every paired observation, then regenerates both reports. Large binaries and source snapshots remain local under ignored `benchmarks/.build`; JSON records and manifests retain their hashes. Production uses no Accelerate/MPSGraph numerical implementation.']
(R/'gpu-upload-cache-atomic-2026-10-29.md').write_text('\n'.join(lines)+'\n')
print('Audited atomic accounting: 200 tests, 432 outputs, and all long-batch observations.')
